import java.util.ArrayList;

public class Warteschlange {

    public static void main(String[] args) {
        ArrayList<String> warteschlange = new ArrayList<>();
        warteschlange.add("Kunde A");
        warteschlange.add("Kunde B");
        warteschlange.add("Kunde C");

        System.out.println("Nächster: " + warteschlange.get(0));
        warteschlange.remove(0);
        System.out.println("Neuer Nächster: " + warteschlange.get(0));
        System.out.println("Wartende: " + warteschlange.size());
    }
}

